@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* one overlay band, ordered by DOM (§12.1 L1). "Scale 0.96 → 1 + fade, easing/spring, origin =
     trigger. Exit: fade 140 ms" (the Dropdown Menu master); the opacity reuses the spring's duration,
     which stays 120 ms when reduced, so the fade survives and the scale does not travel. */
  .nz-menu-popup {
    z-index: var(--nz-z-overlay);
    /* the minimum is the whole popup, border included, so it matches its trigger's width with or
       without a page reset (§8.1) */
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-inline-size: max(12rem, var(--nz-trigger-width, 0px));
    max-block-size: var(--nz-available-height);
    overflow: auto;
    border: var(--nz-border-width-default) solid var(--nz-menu-border, var(--nz-border-subtle));
    border-radius: var(--nz-menu-radius, var(--nz-radius-lg));
    background: var(--nz-menu-bg, var(--nz-bg-surface-raised));
    box-shadow: var(--nz-menu-shadow, var(--nz-elevation-3));
    transform-origin: var(--nz-transform-origin);
    transition:
      scale var(--nz-duration-spring) var(--nz-easing-spring),
      opacity var(--nz-duration-spring) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
      scale: var(--nz-scale-enter);
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }
  }

  .nz-menu-list,
  .nz-menu-group,
  .nz-menu-radio-group {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-0-5);
  }

  .nz-menu-list {
    padding: var(--nz-space-1-5);
    outline: none;
  }

  .nz-menu-item,
  .nz-menu-checkbox-item,
  .nz-menu-radio-item {
    display: flex;
    align-items: center;
    gap: var(--nz-space-2);
    /* 36 px rows with or without a page reset (§8.1): the minimum includes the padding */
    box-sizing: border-box;
    min-block-size: 2.25rem;
    padding-block: var(--nz-space-1-5);
    padding-inline: var(--nz-space-3);
    border-radius: var(--nz-radius-sm);
    color: var(--nz-text-primary);
    font: var(--nz-font-body-m);
    letter-spacing: var(--nz-tracking-body-m);
    text-decoration: none;
    cursor: default;

    /* a pointer hint only (1.08:1 on the surface); keyboard focus is the generated ring */
    &[data-highlighted] {
      background: var(--nz-bg-hover);
    }

    &[data-tone='critical'] {
      color: var(--nz-text-critical);
    }

    /* checked wins over highlighted: the selection stays visible under the pointer */
    &[data-checked] {
      background: var(--nz-bg-brand-subtle);
      color: var(--nz-text-brand);
    }

    &[data-checked][data-highlighted] {
      background: var(--nz-bg-hover);
    }

    &[data-disabled] {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }
  }

  /* a menu that holds checkable items reserves their check column on plain items too, so every
     shortcut lines up */
  .nz-menu-list:has(.nz-menu-item-indicator) .nz-menu-item {
    padding-inline-end: calc(var(--nz-space-3) + var(--nz-size-icon-sm) + var(--nz-space-2));
  }

  .nz-menu-item-icon,
  .nz-menu-item-indicator {
    display: inline-flex;
    flex: none;
    /* internal and @nizivo/icons glyphs are 1em: size them to the 16 px icon slot */
    font-size: var(--nz-size-icon-sm);
  }

  .nz-menu-item-icon {
    color: var(--nz-icon-secondary);
  }

  .nz-menu-item-label {
    flex: 1;
    min-inline-size: 0;
  }

  .nz-menu-list .nz-menu-item-shortcut {
    flex: none;
    padding: 0;
    border: 0;
    background: none;
    color: var(--nz-text-tertiary);
  }

  .nz-menu-item-indicator {
    visibility: hidden;
    color: var(--nz-icon-brand);
  }

  .nz-menu-list [data-checked] > .nz-menu-item-indicator {
    visibility: visible;
  }

  .nz-menu-list [data-checked] > .nz-menu-item-icon {
    color: var(--nz-icon-brand);
  }

  .nz-menu-list [data-tone='critical'] > .nz-menu-item-icon {
    color: var(--nz-icon-critical);
  }

  .nz-menu-list [data-disabled] > :is(.nz-menu-item-icon, .nz-menu-item-shortcut) {
    color: inherit;
  }

  .nz-menu-group-label {
    padding-block: var(--nz-space-1-5) var(--nz-space-1);
    padding-inline-start: var(--nz-space-3);
    color: var(--nz-text-tertiary);
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
  }

  .nz-menu-separator {
    flex: none;
    block-size: var(--nz-border-width-default);
    background: var(--nz-border-subtle);
  }

  @media (forced-colors: active) {
    .nz-menu-popup {
      border: 1px solid CanvasText;
    }

    /* base.css's [data-checked] floor (Highlight) loses to [data-highlighted]'s background above, a
       later layer, so repeat it here, as select.css does for [data-selected] (§8.5). The second
       selector outranks the checked-and-highlighted hover fill, which would otherwise paint a token
       colour under HighlightText (week 5 visual lane) */
    :is(.nz-menu-checkbox-item, .nz-menu-radio-item)[data-checked],
    :is(.nz-menu-checkbox-item, .nz-menu-radio-item)[data-checked][data-highlighted] {
      background: Highlight;
      color: HighlightText;
      /* forced-color-adjust is inherited, so the ring and the glyphs would keep their token colours.
         The rows carry data-focus-inset, so the keyboard ring is drawn inside the Highlight fill,
         where HighlightText shows, as Select's does (CanvasText there was about 1.9:1 against the
         fill: week 6 review) */
      outline-color: HighlightText;
      /* one ring width further in, so Highlight shows on both sides of it: at the row's edge it
         would sit against the Canvas around the row and read as the fill shrinking */
      outline-offset: calc(-2 * var(--nz-border-width-focus));
      forced-color-adjust: none;

      & > :is(.nz-menu-item-icon, .nz-menu-item-shortcut, .nz-menu-item-indicator) {
        color: HighlightText;
      }
    }

    /* the items are divs with aria-disabled, which the browser does not grey out */
    :is(.nz-menu-item, .nz-menu-checkbox-item, .nz-menu-radio-item)[data-disabled] {
      color: GrayText;
    }

    .nz-menu-separator {
      background: CanvasText;
    }
  }
}
